(function(){
  let t=0;
  function hexToRgb(hex){ hex=hex.replace('#',''); const n=parseInt(hex,16); return [(n>>16)&255,(n>>8)&255,n&255]; }
  const cols = PALETTE.map(hexToRgb);

  const strands = [];
  const strandCount = 5;
  for(let i=0;i<strandCount;i++){
    strands.push({
      side: i%2===0?'left':'right',
      yBase: Math.random()*0.35 + (i%2===0?0.06:0.55),
      amp: 36+Math.random()*55,
      speed: 0.18+Math.random()*0.28,
      phase: Math.random()*Math.PI*2,
      width: 2+Math.random()*3,
      colorIdx: i%cols.length,
      len: 0.22+Math.random()*0.14
    });
  }

  const particles = [];
  const pCount = 110;
  for(let i=0;i<pCount;i++){
    particles.push({
      x: Math.random(),
      y: Math.random(),
      r: 0.5+Math.random()*1.7,
      speed: 0.05+Math.random()*0.11,
      drift: (Math.random()-0.5)*0.028,
      phase: Math.random()*Math.PI*2,
      colorIdx: Math.floor(Math.random()*cols.length)
    });
  }

  const fogs = [];
  for(let i=0;i<4;i++){
    fogs.push({
      x: i%2===0 ? 0.08+Math.random()*0.14 : 0.76+Math.random()*0.16,
      y: Math.random(),
      r: 140+Math.random()*110,
      speed: 0.018+Math.random()*0.03,
      phase: Math.random()*Math.PI*2,
      colorIdx: i%cols.length
    });
  }

  function draw(){
    const w=W(), h=H();
    ctx.clearRect(0,0,w,h);
    t+=0.008;

    fogs.forEach(f=>{
      const cx = f.x*w + Math.sin(t*f.speed+f.phase)*18;
      const cy = f.y*h + Math.cos(t*f.speed*0.8+f.phase)*18;
      const grad = ctx.createRadialGradient(cx,cy,0,cx,cy,f.r);
      const c = cols[f.colorIdx];
      grad.addColorStop(0, 'rgba('+c[0]+','+c[1]+','+c[2]+',0.10)');
      grad.addColorStop(1, 'rgba('+c[0]+','+c[1]+','+c[2]+',0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx,cy,f.r,0,Math.PI*2);
      ctx.fill();
    });

    strands.forEach(s=>{
      const c = cols[s.colorIdx];
      ctx.save();
      ctx.lineCap='round';
      ctx.lineWidth = s.width;
      ctx.shadowBlur = 12;
      ctx.shadowColor = 'rgba('+c[0]+','+c[1]+','+c[2]+',0.5)';
      ctx.strokeStyle = 'rgba('+c[0]+','+c[1]+','+c[2]+',0.55)';
      ctx.beginPath();
      const steps=40;
      for(let i=0;i<=steps;i++){
        const p=i/steps;
        let xBase;
        if(s.side==='left'){ xBase = p*s.len*w; } else { xBase = w - p*s.len*w; }
        const y = s.yBase*h + Math.sin(p*Math.PI*2.2 + t*s.speed*2 + s.phase)*s.amp*(1-p*0.3);
        if(i===0) ctx.moveTo(xBase,y); else ctx.lineTo(xBase,y);
      }
      ctx.stroke();
      ctx.restore();
    });

    particles.forEach(p=>{
      p.y -= p.speed*0.003;
      p.x += p.drift*0.003;
      if(p.y<-0.05){ p.y=1.05; p.x=Math.random(); }
      if(p.x<-0.05) p.x=1.05;
      if(p.x>1.05) p.x=-0.05;
      const px = p.x*w, py = p.y*h;
      const c = cols[p.colorIdx];
      const shimmer = 0.4+0.5*Math.sin(t*2+p.phase);
      ctx.beginPath();
      ctx.fillStyle = 'rgba('+c[0]+','+c[1]+','+c[2]+','+(0.28+shimmer*0.38)+')';
      ctx.arc(px,py,p.r,0,Math.PI*2);
      ctx.fill();
    });

    requestAnimationFrame(draw);
  }
  draw();
})();
